export type Options<
  TData extends TDataShape = TDataShape,
  ThrowOnError extends boolean = boolean,
> = Options2<TData, ThrowOnError> & {
  /**
   * You can provide a client instance returned by `createClient()` instead of
   * individual options. This might be also useful if you want to implement a
   * custom client.
   */
  client?: Client;
  /**
   * You can pass arbitrary values through the `meta` object. This can be
   * used to access values that aren't defined as part of the SDK function.
   */
  meta?: Record<string, unknown>;
};

export class Health {
  /**
   * Liveness check
   */
  public static healthControllerCheck<ThrowOnError extends boolean = false>(
    options?: Options<HealthControllerCheckData, ThrowOnError>,
  ) {
    return (options?.client ?? client).get<HealthControllerCheckResponses, unknown, ThrowOnError>({
      url: '/health',
      ...options,
    });
  }
}

export class AuthEmailOtp {
  /**
   * Send registration OTP (email)
   *
   * Starts email-based registration for a **new** member. Proxies to the Yamauchi API, which creates an inactive user and emails a 6-digit OTP. Confirm it via `POST /auth/email/confirm`. Public endpoint.
   *
   * If the email already belongs to a registered account, Yamauchi rejects it with `E-AUTH-020` (409). Too many requests (Yamauchi throttles OTP sends) → `E-RATE-001` (429). A Yamauchi outage surfaces as `E-EXT-001` / `E-EXT-002` (502).
   */
  public static emailOtpControllerRegister<ThrowOnError extends boolean = false>(
    options: Options<EmailOtpControllerRegisterData, ThrowOnError>,
  ) {
    return (options.client ?? client).post<
      EmailOtpControllerRegisterResponses,
      EmailOtpControllerRegisterErrors,
      ThrowOnError
    >({
      url: '/api/v1/auth/email/register',
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...options.headers,
      },
    });
  }

  /**
   * Send login OTP (email)
   *
   * Starts email-based login for an **existing** member by emailing a 6-digit OTP (confirm via `POST /auth/email/confirm`). Public endpoint.
   *
   * If the email is not registered → `E-AUTH-021` (404); if it belongs to a social-login account (no password/OTP flow) → `E-AUTH-022` (409). Too many requests (Yamauchi throttles OTP sends) → `E-RATE-001` (429). A Yamauchi outage surfaces as `E-EXT-001` / `E-EXT-002` (502).
   */
  public static emailOtpControllerLogin<ThrowOnError extends boolean = false>(
    options: Options<EmailOtpControllerLoginData, ThrowOnError>,
  ) {
    return (options.client ?? client).post<
      EmailOtpControllerLoginResponses,
      EmailOtpControllerLoginErrors,
      ThrowOnError
    >({
      url: '/api/v1/auth/email/login',
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...options.headers,
      },
    });
  }

  /**
   * Verify email OTP
   *
   * Verifies the 6-digit OTP for **both registration and login** flows and, on success, issues a fitness JWT token pair. Public endpoint.
   *
   * An incorrect or expired code → `E-AUTH-023` (401). A Yamauchi outage surfaces as `E-EXT-001` / `E-EXT-002` (502).
   */
  public static emailOtpControllerConfirm<ThrowOnError extends boolean = false>(
    options: Options<EmailOtpControllerConfirmData, ThrowOnError>,
  ) {
    return (options.client ?? client).post<
      EmailOtpControllerConfirmResponses,
      EmailOtpControllerConfirmErrors,
      ThrowOnError
    >({
      url: '/api/v1/auth/email/confirm',
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...options.headers,
      },
    });
  }

  /**
   * Resend email OTP
   *
   * Invalidates the previously issued OTP and emails a fresh one. Public endpoint. Resends are rate-limited — exceeding the allowance returns `E-RATE-003` (429). A Yamauchi outage surfaces as `E-EXT-001` / `E-EXT-002` (502).
   *
   * `type` / `isPending` are forwarded to Yamauchi and pick which address it looks up: the registered one (default), or — `isPending: true` or `type: "update"` — the address still pending verification (会員情報登録 / contact change). No such address → `E-AUTH-021` (404). While the Yamauchi User API is disabled (dev) a pending address was never sent to Yamauchi, so a pending resend is a no-op 204.
   */
  public static emailOtpControllerResend<ThrowOnError extends boolean = false>(
    options: Options<EmailOtpControllerResendData, ThrowOnError>,
  ) {
    return (options.client ?? client).post<
      EmailOtpControllerResendResponses,
      EmailOtpControllerResendErrors,
      ThrowOnError
    >({
      url: '/api/v1/auth/email/resend',
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...options.headers,
      },
    });
  }
}

