export class AuthToken {
  /**
   * Refresh access token
   *
   * Exchanges a valid refresh token for a **new access + refresh token pair** (rotating session). The presented refresh token is invalidated as part of the rotation. Public endpoint — the refresh token itself is the credential.
   *
   * A token that is expired → `E-AUTH-002`; one with an invalid signature → `E-AUTH-003`; a token whose session no longer exists (logged out, revoked, or evicted as the least recently used device once the member is signed in on more devices than the per-member cap) → `E-AUTH-005`. Signing in on another device does NOT end this one.
   */
  public static tokenControllerRefresh<ThrowOnError extends boolean = false>(
    options: Options<TokenControllerRefreshData, ThrowOnError>,
  ) {
    return (options.client ?? client).post<
      TokenControllerRefreshResponses,
      TokenControllerRefreshErrors,
      ThrowOnError
    >({
      url: '/api/v1/auth/refresh',
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...options.headers,
      },
    });
  }

  /**
   * Logout
   *
   * Ends **this device's** session — the one named by the JWT `sessionId` claim. A member may be signed in on several devices at once (as in legacy), and the others stay signed in. The stored Yamauchi session is logged out (best-effort) only when this was the member's last device. A token minted before the `sessionId` claim existed ends every session, as logout always did. **Idempotent** — the backend never raises a business error, so a missing/already-gone session still returns 204.
   */
  public static tokenControllerLogout<ThrowOnError extends boolean = false>(
    options?: Options<TokenControllerLogoutData, ThrowOnError>,
  ) {
    return (options?.client ?? client).post<
      TokenControllerLogoutResponses,
      TokenControllerLogoutErrors,
      ThrowOnError
    >({
      security: [{ scheme: 'bearer', type: 'http' }],
      url: '/api/v1/auth/logout',
      ...options,
    });
  }
}

