export class AdminDomainMaster {
  /**
   * List domain masters (API-071 §3)
   *
   * Lists the CRM access allowlist — management name, domain, authentication route, active-staff count and 状態 — with the Y-14 FR-M001 search and filter. **HQ-only**.
   *
   * Deactivated domains are **included**: the row keeps its place in the list wearing a 無効 badge, and there is no filter that hides it.
   */
  public static adminDomainMasterControllerList<ThrowOnError extends boolean = false>(
    options?: Options<AdminDomainMasterControllerListData, ThrowOnError>,
  ) {
    return (options?.client ?? client).get<
      AdminDomainMasterControllerListResponses,
      AdminDomainMasterControllerListErrors,
      ThrowOnError
    >({
      security: [{ scheme: 'bearer', type: 'http' }],
      url: '/api/v1/admin/domain-master',
      ...options,
    });
  }

  /**
   * Register a domain (API-071 §4)
   *
   * Adds a domain to the CRM access allowlist (domain normalized to lowercase). **HQ-only**. A duplicate domain → `E-DMN-001` (409).
   *
   * The registration form carries no status field — a new domain is always created active. Use `PATCH /{id}/active` to suspend it later.
   */
  public static adminDomainMasterControllerRegister<ThrowOnError extends boolean = false>(
    options: Options<AdminDomainMasterControllerRegisterData, ThrowOnError>,
  ) {
    return (options.client ?? client).post<
      AdminDomainMasterControllerRegisterResponses,
      AdminDomainMasterControllerRegisterErrors,
      ThrowOnError
    >({
      security: [{ scheme: 'bearer', type: 'http' }],
      url: '/api/v1/admin/domain-master',
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...options.headers,
      },
    });
  }

  /**
   * Delete a domain master (API-071 §8)
   *
   * Physically deletes the record. **HQ-only**.
   *
   * **Blocked while active staff are attached** → `E-DMN-004` (409): deleting the domain would lock those staff out at their next login. Deactivate (`PATCH /{id}/active`) to suspend access reversibly instead.
   *
   * Once deleted, new invitations (`E-DMN-006`) and logins (`E-DMN-007`) at that domain are refused — the domain is off the allowlist.
   */
  public static adminDomainMasterControllerRemove<ThrowOnError extends boolean = false>(
    options: Options<AdminDomainMasterControllerRemoveData, ThrowOnError>,
  ) {
    return (options.client ?? client).delete<
      AdminDomainMasterControllerRemoveResponses,
      AdminDomainMasterControllerRemoveErrors,
      ThrowOnError
    >({
      security: [{ scheme: 'bearer', type: 'http' }],
      url: '/api/v1/admin/domain-master/{id}',
      ...options,
    });
  }

  /**
   * Domain master detail (API-071 §5)
   *
   * The Y-14 FR-M003 detail screen: the record plus its active-staff count and the read-only 作成者 / 作成日時 fields. **HQ-only**.
   *
   * The **staff list of that screen is not served here** — call `GET /api/v1/admin/staff?emailDomain={domain}` (API-082 §5.2), which already has the pagination, 3-value status and soft-delete exclusion this endpoint would otherwise duplicate.
   */
  public static adminDomainMasterControllerDetail<ThrowOnError extends boolean = false>(
    options: Options<AdminDomainMasterControllerDetailData, ThrowOnError>,
  ) {
    return (options.client ?? client).get<
      AdminDomainMasterControllerDetailResponses,
      AdminDomainMasterControllerDetailErrors,
      ThrowOnError
    >({
      security: [{ scheme: 'bearer', type: 'http' }],
      url: '/api/v1/admin/domain-master/{id}',
      ...options,
    });
  }

  /**
   * Edit a domain master (API-071 §6)
   *
   * Edits the record. All fields optional, at least one required. **HQ-only**.
   *
   * `name` is always editable. `domain` and `authProvider` are **blocked while active staff are attached** → `E-DMN-005` (409): re-pointing a domain its staff depend on would strand them outside the allowlist at their next login. The operational path for an auth-route switch is deactivate the staff in Y-01 → edit here → re-invite.
   *
   * A field carrying the current value is a **no-op**, not a change — so the CRM may PATCH the whole form back unmodified even on a domain that has staff, and `updatedAt` is left alone.
   *
   * `isActive` is **not accepted here** — status moves through `PATCH /{id}/active` only.
   */
  public static adminDomainMasterControllerUpdate<ThrowOnError extends boolean = false>(
    options: Options<AdminDomainMasterControllerUpdateData, ThrowOnError>,
  ) {
    return (options.client ?? client).patch<
      AdminDomainMasterControllerUpdateResponses,
      AdminDomainMasterControllerUpdateErrors,
      ThrowOnError
    >({
      security: [{ scheme: 'bearer', type: 'http' }],
      url: '/api/v1/admin/domain-master/{id}',
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...options.headers,
      },
    });
  }

  /**
   * Activate / deactivate a domain (API-071 §7)
   *
   * Suspends or restores a domain's CRM access **without deleting the row** — the reversible counterpart of DELETE (Y-14 FR-S001). **HQ-only**. Idempotent: setting the value it already has is a no-op that still answers 200.
   *
   * Deactivation is allowed **even while staff are attached** — locking those staff out is the point of the feature. Effects: their next login is refused with `E-DMN-007` (403) and new invitations with `E-DMN-006` (422). **Open sessions are not terminated**; they expire within the 60-minute Redis TTL.
   */
  public static adminDomainMasterControllerSetActive<ThrowOnError extends boolean = false>(
    options: Options<AdminDomainMasterControllerSetActiveData, ThrowOnError>,
  ) {
    return (options.client ?? client).patch<
      AdminDomainMasterControllerSetActiveResponses,
      AdminDomainMasterControllerSetActiveErrors,
      ThrowOnError
    >({
      security: [{ scheme: 'bearer', type: 'http' }],
      url: '/api/v1/admin/domain-master/{id}/active',
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...options.headers,
      },
    });
  }
}

