export class SocialProfile {
  /**
   * View another member's social profile
   *
   * Returns the target member's **public** profile plus the caller's `relationship` (`isFollowing`, `isFollowedBy`, `isMutualFollow`, `followType`, `isMuted`).
   *
   * `gender` / `dateOfBirth` are returned only when the target enabled the matching visibility flag (BR-SOC-005), otherwise `null`.
   *
   * **Opaque 404** (§9.6): a non-existent / withdrawn member, or any block between the two members (either direction), returns the same `E-SNS-030` to avoid leaking existence. Passing the caller's own id returns the full own profile.
   */
  public static socialProfileControllerGetMember<ThrowOnError extends boolean = false>(
    options: Options<SocialProfileControllerGetMemberData, ThrowOnError>,
  ) {
    return (options.client ?? client).get<
      SocialProfileControllerGetMemberResponses,
      SocialProfileControllerGetMemberErrors,
      ThrowOnError
    >({
      security: [{ scheme: 'bearer', type: 'http' }],
      url: '/api/v1/social-profiles/{memberId}',
      ...options,
    });
  }

  /**
   * View another member's posts (D-04 FR-M004)
   *
   * Returns the target member's posts the caller is allowed to see: `everyone` posts, plus `followers_only` posts when the caller actively follows the target. `self_only` / `coach_and_self` are never returned here. A block in either direction yields an empty list. Paginated newest-first.
   */
  public static socialProfileControllerGetMemberPosts<ThrowOnError extends boolean = false>(
    options: Options<SocialProfileControllerGetMemberPostsData, ThrowOnError>,
  ) {
    return (options.client ?? client).get<
      SocialProfileControllerGetMemberPostsResponses,
      SocialProfileControllerGetMemberPostsErrors,
      ThrowOnError
    >({
      security: [{ scheme: 'bearer', type: 'http' }],
      url: '/api/v1/social-profiles/{memberId}/posts',
      ...options,
    });
  }

  /**
   * Get own social profile
   *
   * Returns the authenticated member's full social profile, including the private fields `gender` and `dateOfBirth` (read from MemberService — Yamauchi-mastered) and the live `followerCount` / `followingCount`.
   *
   * The profile is **created lazily on first access** (BR-SOC-001): if none exists yet, one is generated with a random `displayName` (BR-SOC-003) and a randomly selected active preset avatar. `avatarDisplayUrl` is the resolved icon URL (custom upload or preset).
   */
  public static socialProfileControllerGetOwn<ThrowOnError extends boolean = false>(
    options?: Options<SocialProfileControllerGetOwnData, ThrowOnError>,
  ) {
    return (options?.client ?? client).get<
      SocialProfileControllerGetOwnResponses,
      SocialProfileControllerGetOwnErrors,
      ThrowOnError
    >({
      security: [{ scheme: 'bearer', type: 'http' }],
      url: '/api/v1/social-profiles/me',
      ...options,
    });
  }

  /**
   * Update own social profile
   *
   * Partial update (PATCH semantics): send only the fields to change. Sending `null` clears a nullable field.
   *
   * **Avatar (mutually exclusive)** — a profile always has exactly one avatar. Setting `avatarUrl` clears `avatarPresetId` and vice-versa. Setting both → `E-SNS-033`; clearing both → `E-SNS-034`; an unknown preset → `E-SNS-031`; an `avatarUrl` not issued by the avatar presign endpoint → `E-SNS-032`.
   *
   * **Gender / DOB** are Yamauchi-mastered (API-039 §9.5): they are forwarded to MemberService (which proxies the Yamauchi API) **before** the local write, so a Yamauchi failure surfaces as `E-EXT-001` and nothing is persisted. The profile row itself only owns the visibility flags.
   */
  public static socialProfileControllerUpdate<ThrowOnError extends boolean = false>(
    options: Options<SocialProfileControllerUpdateData, ThrowOnError>,
  ) {
    return (options.client ?? client).patch<
      SocialProfileControllerUpdateResponses,
      SocialProfileControllerUpdateErrors,
      ThrowOnError
    >({
      security: [{ scheme: 'bearer', type: 'http' }],
      url: '/api/v1/social-profiles/me',
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...options.headers,
      },
    });
  }

  /**
   * Issue a presigned URL for avatar upload
   *
   * Returns a short-lived S3 presigned **PUT** URL for uploading a custom avatar image (JPEG or PNG, ≤ 5 MB — BR-SOC-002). Flow: (1) call this endpoint, (2) `PUT` the image bytes to `presignedUrl`, (3) call `PATCH /social-profiles/me` with the returned `avatarUrl`.
   *
   * Response: `{ presignedUrl, avatarUrl, expiresAt }`. Backed by the media service (`social-avatar` upload tag).
   */
  public static socialProfileControllerAvatarPresign<ThrowOnError extends boolean = false>(
    options: Options<SocialProfileControllerAvatarPresignData, ThrowOnError>,
  ) {
    return (options.client ?? client).post<
      SocialProfileControllerAvatarPresignResponses,
      SocialProfileControllerAvatarPresignErrors,
      ThrowOnError
    >({
      security: [{ scheme: 'bearer', type: 'http' }],
      url: '/api/v1/social-profiles/me/avatar/presigned-url',
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...options.headers,
      },
    });
  }

  /**
   * List preset avatar icons
   *
   * Returns the catalogue of active preset avatar icons (`{ presets: [{ presetId, imageUrl, sortOrder }] }`), ordered by `sortOrder`. Use a `presetId` as `avatarPresetId` in `PATCH /social-profiles/me`.
   */
  public static socialProfileControllerListPresets<ThrowOnError extends boolean = false>(
    options?: Options<SocialProfileControllerListPresetsData, ThrowOnError>,
  ) {
    return (options?.client ?? client).get<
      SocialProfileControllerListPresetsResponses,
      SocialProfileControllerListPresetsErrors,
      ThrowOnError
    >({
      security: [{ scheme: 'bearer', type: 'http' }],
      url: '/api/v1/avatar-presets',
      ...options,
    });
  }
}

