export class Media {
  /**
   * Issue a presigned PUT URL for a single-file S3 upload (≤100MB)
   *
   * Issues an S3 presigned **PUT** URL for a single file (1 byte – 100 MB) and creates a `pending` upload session record. The `tag` selects the access level and target S3 prefix and is validated against a server-side whitelist: a format-valid but unknown tag → 400 E-MED-011, a missing/invalid tag or other body validation → 400 E-VAL-001, and a file name with no derivable extension → 400 E-MED-006.
   *
   * A file larger than 100 MB → 422 E-MED-001 and a content type outside the global whitelist → 422 E-MED-002. Response: `{ uploadId, url, method, s3Key, expiresIn, requiredHeaders }`. The client then PUTs the bytes to `url` itself — the API never receives them — sending **every** header in `requiredHeaders` verbatim: they are part of the signature and S3 rejects the upload with 403 SignatureDoesNotMatch without them. `s3Key` is the value to send back to whichever endpoint stores the reference (e.g. `facePhotoS3Key` on `PATCH /members/me`).
   */
  public static mediaControllerPresign<ThrowOnError extends boolean = false>(
    options: Options<MediaControllerPresignData, ThrowOnError>,
  ) {
    return (options.client ?? client).post<
      MediaControllerPresignResponses,
      MediaControllerPresignErrors,
      ThrowOnError
    >({
      security: [{ scheme: 'bearer', type: 'http' }],
      url: '/api/v1/media/presign',
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...options.headers,
      },
    });
  }

  /**
   * Issue a CloudFront signed cookie for private media access
   *
   * Issues a CloudFront signed cookie granting the authenticated actor delivery access to authenticated-tier media (`member-shared*` + `private*`). The request body is empty — the JWT `sub` identifies the requestor. On success three cookies (`CloudFront-Policy`, `CloudFront-Signature`, `CloudFront-Key-Pair-Id`) are returned via `Set-Cookie` (`Path=/`, `Secure`, `HttpOnly`, `SameSite=None`, `Max-Age=3600`) and the response body is empty (204).
   *
   * The cookie expires after ~1 hour; the client re-calls this endpoint for a fresh cookie. `public*` media needs no cookie.
   */
  public static mediaControllerSessions<ThrowOnError extends boolean = false>(
    options?: Options<MediaControllerSessionsData, ThrowOnError>,
  ) {
    return (options?.client ?? client).post<
      MediaControllerSessionsResponses,
      MediaControllerSessionsErrors,
      ThrowOnError
    >({
      security: [{ scheme: 'bearer', type: 'http' }],
      url: '/api/v1/media/sessions',
      ...options,
    });
  }

  /**
   * Stable asset URL — redirects to a signed S3 GET URL
   *
   * The permanent URL for a stored object; every image/video field in this API points here. Responds `302` to a short-lived signed S3 URL, so clients can cache and store this URL indefinitely and treat it as the object identity.
   *
   * `public*` keys need no token. `member-shared*` needs any valid token. `private*` needs the uploader or a CRM staff token, except `social-avatar` / `social-media`, which any authenticated member may read (feeds render other members’ avatars and post media).
   *
   * Auth accepts `Authorization: Bearer`, the ADR-038 compat auth cookie, or the `exp`/`sig` capability query the read paths append — send the URL back exactly as it was returned and a plain `<img src>` / `Image.network` / `CachedNetworkImage` renders it with no headers at all. Strip the query and the same URL needs a token again.
   */
  public static mediaAssetControllerGet<ThrowOnError extends boolean = false>(
    options: Options<MediaAssetControllerGetData, ThrowOnError>,
  ) {
    return (options.client ?? client).get<unknown, unknown, ThrowOnError>({
      url: '/api/v1/media/assets/{path}',
      ...options,
    });
  }
}

