export class AdminTermsDocumentManagementApi076 {
  /**
   * List & search terms documents (API-076 §3)
   *
   * Paginated list. Logically-deleted rows are excluded unless includeDeleted=true. **system / headquarter** see all brands; **manager / staff / observer** are silently scoped to the brand set behind their managed stores (§11.5) and cannot widen it via brandEnum. **trainer** denied. Each row carries a **derived** `status` (下書き / 公開中 / 適用終了) computed from its effective window in JST — there is no stored publication flag.
   */
  public static adminTermsControllerList<ThrowOnError extends boolean = false>(
    options?: Options<AdminTermsControllerListData, ThrowOnError>,
  ) {
    return (options?.client ?? client).get<
      AdminTermsControllerListResponses,
      AdminTermsControllerListErrors,
      ThrowOnError
    >({
      security: [{ scheme: 'bearer', type: 'http' }],
      url: '/api/v1/admin/terms',
      ...options,
    });
  }

  /**
   * Register a terms document (API-076 §5)
   *
   * Creates an ORIGINAL (parentTermsId = null). The PDF must already be uploaded via API-006 (tag=terms); only its S3 key is passed here. `bodyText` is **required** alongside `pdfS3Key` (v0.8 §5.2, method D): the client extracts the text from the PDF it uploaded and posts it — the server never parses the PDF. **system / headquarter only** (E-AUTH-103 otherwise).
   */
  public static adminTermsControllerCreate<ThrowOnError extends boolean = false>(
    options: Options<AdminTermsControllerCreateData, ThrowOnError>,
  ) {
    return (options.client ?? client).post<
      AdminTermsControllerCreateResponses,
      AdminTermsControllerCreateErrors,
      ThrowOnError
    >({
      security: [{ scheme: 'bearer', type: 'http' }],
      url: '/api/v1/admin/terms',
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...options.headers,
      },
    });
  }

  /**
   * Get the caller’s terms brand scope (API-076 §11.5)
   *
   * The brand GROUPS the caller’s list/detail reads are scoped to, so the CRM can pin its brand select. **system / headquarter** → `brandGroups: null` (unrestricted). **manager / staff / observer** → the distinct groups behind their own stores (own store ∪ managed stores ∪ every store of their FC company), resolved server-side (observer included, although it cannot read the store master). **trainer** denied (E-AUTH-100).
   */
  public static adminTermsControllerBrandScope<ThrowOnError extends boolean = false>(
    options?: Options<AdminTermsControllerBrandScopeData, ThrowOnError>,
  ) {
    return (options?.client ?? client).get<
      AdminTermsControllerBrandScopeResponses,
      AdminTermsControllerBrandScopeErrors,
      ThrowOnError
    >({
      security: [{ scheme: 'bearer', type: 'http' }],
      url: '/api/v1/admin/terms/brand-scope',
      ...options,
    });
  }

  /**
   * Logically delete a terms document (API-076 §7)
   *
   * Sets deleted_at. Physical delete is never performed — terms_consents references the row and the revision history must survive. Deleted rows remain retrievable via includeDeleted=true. Re-issuing on an already-deleted id → 404. **system / headquarter only**.
   */
  public static adminTermsControllerRemove<ThrowOnError extends boolean = false>(
    options: Options<AdminTermsControllerRemoveData, ThrowOnError>,
  ) {
    return (options.client ?? client).delete<
      AdminTermsControllerRemoveResponses,
      AdminTermsControllerRemoveErrors,
      ThrowOnError
    >({
      security: [{ scheme: 'bearer', type: 'http' }],
      url: '/api/v1/admin/terms/{id}',
      ...options,
    });
  }

  /**
   * Get terms document detail (API-076 §4)
   *
   * Full field set + relatedVersions[] — every row in the same original group (anchored on parentTermsId ?? id), so the screen can show the whole revision history; each entry carries its own `remarks` (change note) but no PDF — fetch that version's detail for its PDF. v0.8 §4.3 adds the 規約本文 card fields (`bodyText`, `pdfFileName`, `pdfFileSize`) and the audit **names** (`createdByName` / `updatedByName`, resolved from auth-svc `staffs` in one batched call that can never fail the read). `pdfUrl` is the delivery URL of the PDF (§11.4); `pdfFileName` / `pdfFileSize` come from media-svc `upload_sessions` and are null only when the upload session cannot be resolved.
   */
  public static adminTermsControllerDetail<ThrowOnError extends boolean = false>(
    options: Options<AdminTermsControllerDetailData, ThrowOnError>,
  ) {
    return (options.client ?? client).get<
      AdminTermsControllerDetailResponses,
      AdminTermsControllerDetailErrors,
      ThrowOnError
    >({
      security: [{ scheme: 'bearer', type: 'http' }],
      url: '/api/v1/admin/terms/{id}',
      ...options,
    });
  }

  /**
   * Edit a terms document (API-076 §6)
   *
   * Partial update of the editable set. `termsType` and `brandEnum` are edit-locked (identity/routing — changing them would orphan consent records): sending either is rejected with 400 E-VAL-001. The effective range is revalidated on the MERGED row. **§6.2 PDF/text pairing rule**: `pdfS3Key` without `bodyText` → 400 E-VAL-001; `bodyText` on its own is allowed (typo fix in the extracted text). **system / headquarter only**.
   */
  public static adminTermsControllerUpdate<ThrowOnError extends boolean = false>(
    options: Options<AdminTermsControllerUpdateData, ThrowOnError>,
  ) {
    return (options.client ?? client).patch<
      AdminTermsControllerUpdateResponses,
      AdminTermsControllerUpdateErrors,
      ThrowOnError
    >({
      security: [{ scheme: 'bearer', type: 'http' }],
      url: '/api/v1/admin/terms/{id}',
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...options.headers,
      },
    });
  }

  /**
   * Create a new version (API-076 §8)
   *
   * Inserts a new version and closes the prior one in ONE transaction: the source row's effectiveTo is closed at the new effectiveFrom − 1 day (only ever shortened: a source that already ends earlier keeps its own effectiveTo), so exactly one version of a (termsType, brand) is ever effective. `parentTermsId` is set to the ORIGINAL (stable group anchor) and `prevTermsId` to the source (linked list). termsType/brandEnum are inherited — sending them → 400 E-VAL-001. `bodyText` is **required** (v0.8 §8.2) and never inherited from the source: a revised PDF must bring its own client-extracted text. **system / headquarter only**.
   */
  public static adminTermsControllerCreateVersion<ThrowOnError extends boolean = false>(
    options: Options<AdminTermsControllerCreateVersionData, ThrowOnError>,
  ) {
    return (options.client ?? client).post<
      AdminTermsControllerCreateVersionResponses,
      AdminTermsControllerCreateVersionErrors,
      ThrowOnError
    >({
      security: [{ scheme: 'bearer', type: 'http' }],
      url: '/api/v1/admin/terms/{id}/versions',
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...options.headers,
      },
    });
  }
}

export class AdminLockerSlotOperationsApi101 {
  /**
   * List pending-release slots (API-101 §4.1, FR-008)
   *
   * The cleaning worklist: slots the daily batch moved to `pending_release` that are not cleaned yet (`cleaned_at IS NULL`). Each row carries the former member and the cancellation date of the locker option contract so the crew can work straight off it. Filters (store, location, cancellation-date range) are applied before paging. Sort: the key NULLS LAST in both directions, ties `created_at DESC, id ASC`.
   */
  public static adminLockerSlotOpsControllerListPendingRelease<
    ThrowOnError extends boolean = false,
  >(options?: Options<AdminLockerSlotOpsControllerListPendingReleaseData, ThrowOnError>) {
    return (options?.client ?? client).get<
      AdminLockerSlotOpsControllerListPendingReleaseResponses,
      AdminLockerSlotOpsControllerListPendingReleaseErrors,
      ThrowOnError
    >({
      security: [{ scheme: 'bearer', type: 'http' }],
      url: '/api/v1/admin/locker-slots/pending-release',
      ...options,
    });
  }

  /**
   * CSV of the pending-release worklist (API-101 §7.1, FR-008)
   *
   * Same filters and store scope as the list, no pagination. Ordered like the list default (releaseDate ASC). More than 10,000 matching rows → 400 E-VAL-001 and no file (v0.10).
   */
  public static adminLockerSlotOpsControllerExportPendingRelease<
    ThrowOnError extends boolean = false,
  >(options?: Options<AdminLockerSlotOpsControllerExportPendingReleaseData, ThrowOnError>) {
    return (options?.client ?? client).get<
      AdminLockerSlotOpsControllerExportPendingReleaseResponses,
      AdminLockerSlotOpsControllerExportPendingReleaseErrors,
      ThrowOnError
    >({
      security: [{ scheme: 'bearer', type: 'http' }],
      url: '/api/v1/admin/locker-slots/pending-release/export',
      ...options,
    });
  }

  /**
   * Open many cleaned slots at once (API-101 §6.4, FR-007)
   *
   * One atomic transaction over 1–50 slot ids (duplicates are applied once). Checks over the whole batch, in order: any slot outside your store scope → 403 E-LOC-100; any slot not `pending_release` → 422 E-LOC-012; any unknown slot id → 404 E-LOC-002. On any error nothing is written and the error body also carries `processed[]` (the offending slots carry `errorCode`, all are `failed`) and `summary`. Each opened slot becomes `available` with `cleanedAt`, its former contract back-reference is cleared and a history row is appended.
   */
  public static adminLockerSlotOpsControllerOpenBulk<ThrowOnError extends boolean = false>(
    options: Options<AdminLockerSlotOpsControllerOpenBulkData, ThrowOnError>,
  ) {
    return (options.client ?? client).post<
      AdminLockerSlotOpsControllerOpenBulkResponses,
      AdminLockerSlotOpsControllerOpenBulkErrors,
      ThrowOnError
    >({
      security: [{ scheme: 'bearer', type: 'http' }],
      url: '/api/v1/admin/locker-slots/open-bulk',
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...options.headers,
      },
    });
  }

  /**
   * Assign a slot to a member (API-101 §6.1, FR-005)
   *
   * One transaction: the slot becomes `in_use` (cleanedAt cleared), the main contract gets its lockerSlotId, an option contract is created with the given `optionId` and `startDate` — status `active` when startDate is today, `pending_start` when it is the 1st of next month (the daily batch starts it) — and the transition is logged. Checks in order: contractId / optionId exist, startDate is today or the 1st of next month JST (else `invalid_date`; a past date `too_small`) (400 E-VAL-001); another contract already points at the slot (409 E-LOC-014); slot not `available` (422 E-LOC-010); stale `expectedSlotUpdatedAt` (422 E-LOC-013); contract already holds a slot (409 E-LOC-014); unpaid balance (409 E-LOC-011; unreadable → 500 E-SYS-001); contract not active (422 E-LOC-013); contract store ≠ cabinet store or member deleted (400 E-VAL-001); the main contract already has a live row of this option (409 E-LOC-014). `optionId` must be a locker fee option (category `locker_option`, or an option this slot / cabinet bills with) and active — otherwise 400 E-VAL-001; a mismatch with the slot default is only logged.
   */
  public static adminLockerSlotOpsControllerAssign<ThrowOnError extends boolean = false>(
    options: Options<AdminLockerSlotOpsControllerAssignData, ThrowOnError>,
  ) {
    return (options.client ?? client).post<
      AdminLockerSlotOpsControllerAssignResponses,
      AdminLockerSlotOpsControllerAssignErrors,
      ThrowOnError
    >({
      security: [{ scheme: 'bearer', type: 'http' }],
      url: '/api/v1/admin/locker-slots/{slotId}/contract',
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...options.headers,
      },
    });
  }

  /**
   * File a release (解約) on an in-use slot (API-101 §6.2, FR-006)
   *
   * Sets the cancellation date on the slot's locker option contract ONLY (`end_date`, `updated_by`; status `pending_cancel`, or `cancelled` when the date is not after the option's start date; a `pending_start` (「翌月から」) locker withdrawn before its start becomes `cancelled`). The member's other options are not touched. The slot status is NOT moved and no history row is written: the member keeps the locker through the cancellation date, and the daily batch moves the slot to `pending_release` after it. `reason` is accepted but has no column to be stored in yet. The locker row is picked by the §4.2 rule (live row first, else the latest cancelled one). Checks in order: `cancellationDate` (400 E-VAL-001); slot not `in_use` (422 E-LOC-013); stale `expectedSlotUpdatedAt` (422 E-LOC-013); already filed — the row is `pending_cancel`, or `cancelled` while the slot is still in use (422 E-LOC-013); no locker option contract (422 E-LOC-017); a `pending_start` row dated on / after its start (422 E-LOC-013); after the main contract end date (400 E-VAL-001); the main contract is in its cancellation-fee period (422 E-LOC-015) — except when `cancellationDate` = the main contract end date, or for a `pending_start` row withdrawn before its start. "Not started" is judged by status, not start date: a sign-up row created `active` with a future usage start is a normal active row (v0.10.1).
   */
  public static adminLockerSlotOpsControllerRelease<ThrowOnError extends boolean = false>(
    options: Options<AdminLockerSlotOpsControllerReleaseData, ThrowOnError>,
  ) {
    return (options.client ?? client).post<
      AdminLockerSlotOpsControllerReleaseResponses,
      AdminLockerSlotOpsControllerReleaseErrors,
      ThrowOnError
    >({
      security: [{ scheme: 'bearer', type: 'http' }],
      url: '/api/v1/admin/locker-slots/{slotId}/release',
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...options.headers,
      },
    });
  }

  /**
   * Open one cleaned slot (API-101 §6.3, FR-007)
   *
   * Flips `pending_release` -> `available` after cleaning: sets cleanedAt, clears the former contract back-reference and appends a history row with the note. Checks in order: slot not `pending_release` (422 E-LOC-012); stale `expectedSlotUpdatedAt` (422 E-LOC-013); former contract / its locker option contract missing or inconsistent (422 E-LOC-017). Physical unlock dispatch to the relay controller is not wired yet — this updates state only.
   */
  public static adminLockerSlotOpsControllerOpen<ThrowOnError extends boolean = false>(
    options: Options<AdminLockerSlotOpsControllerOpenData, ThrowOnError>,
  ) {
    return (options.client ?? client).post<
      AdminLockerSlotOpsControllerOpenResponses,
      AdminLockerSlotOpsControllerOpenErrors,
      ThrowOnError
    >({
      security: [{ scheme: 'bearer', type: 'http' }],
      url: '/api/v1/admin/locker-slots/{slotId}/open',
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...options.headers,
      },
    });
  }

  /**
   * Slot transition history (API-101 §5.1, FR-004)
   *
   * Latest first by default. Kept after the slot is soft-deleted. memberNumber / memberName come through the contract; changedByName / changedByRole (current role) from the staff directory. changedBy (API-101 v0.12, ADR-025): a staff id / null = the member through the app (show memberName) / SYSTEM_STAFF_ID = an automatic transition (daily batch, compensation).
   */
  public static adminLockerSlotOpsControllerHistory<ThrowOnError extends boolean = false>(
    options: Options<AdminLockerSlotOpsControllerHistoryData, ThrowOnError>,
  ) {
    return (options.client ?? client).get<
      AdminLockerSlotOpsControllerHistoryResponses,
      AdminLockerSlotOpsControllerHistoryErrors,
      ThrowOnError
    >({
      security: [{ scheme: 'bearer', type: 'http' }],
      url: '/api/v1/admin/locker-slots/{slotId}/status-history',
      ...options,
    });
  }

  /**
   * Cabinet transition history (API-101 #12 §5.3, FR-004)
   *
   * History rows of every slot of the cabinet in one list (the 変更履歴 tab of the locker detail screen), incl. slots removed by a reshape. Latest first by default; ties id ASC. Same item as the slot history plus slotCode.
   */
  public static adminLockerSlotOpsControllerCabinetHistory<ThrowOnError extends boolean = false>(
    options: Options<AdminLockerSlotOpsControllerCabinetHistoryData, ThrowOnError>,
  ) {
    return (options.client ?? client).get<
      AdminLockerSlotOpsControllerCabinetHistoryResponses,
      AdminLockerSlotOpsControllerCabinetHistoryErrors,
      ThrowOnError
    >({
      security: [{ scheme: 'bearer', type: 'http' }],
      url: '/api/v1/admin/lockers/{lockerId}/status-history',
      ...options,
    });
  }
}

